//! Replays this crate's share of the oracle corpus: every `node_path` case
//! must get the answer Bun's `node:path` gave, compared as text. The corpus
//! is regenerated by `tools/oracle/refresh.sh`; nothing here needs Bun.

use std::fs;
use std::path::Path;

use focus_js::json::stringify;
use focus_js::oracle::{KINDS, run_case};
use serde_json::{Value, json};

#[test]
fn every_path_case_gets_buns_answer() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/oracle");
    let cases = fs::read_to_string(dir.join("cases.ndjson")).unwrap();
    let expected = fs::read_to_string(dir.join("expected.ndjson")).unwrap();
    let cases: Vec<&str> = cases.lines().filter(|l| !l.is_empty()).collect();
    let expected: Vec<&str> = expected.lines().filter(|l| !l.is_empty()).collect();
    assert_eq!(
        cases.len(),
        expected.len(),
        "cases.ndjson and expected.ndjson are out of step"
    );

    let (mut replayed, mut win32, mut resolved) = (0, 0, 0);
    let mut differing = Vec::new();
    for (line, want) in cases.iter().zip(&expected) {
        let case: Value = focus_js::json::parse(line).unwrap();
        if !KINDS.contains(&case["kind"].as_str().unwrap_or_default()) {
            continue;
        }
        replayed += 1;
        win32 += usize::from(case["flavour"] == "win32");
        resolved += usize::from(case["op"] == "resolve");
        let out = run_case(&case);
        let got = stringify(&json!({ "id": case["id"], "out": out }));
        if got != *want {
            differing.push(format!(
                "{}\n  upstream: {want}\n  focus:    {got}",
                case["id"]
            ));
        }
    }
    assert!(replayed >= 200, "too few path cases: {replayed}");
    assert!(win32 >= 80 && resolved >= 40, "{win32} {resolved}");
    assert!(
        differing.is_empty(),
        "{} path cases differ from Bun:\n{}",
        differing.len(),
        differing.join("\n")
    );
}
